<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { UserPlus, Search, QrCode, Building2, Clock3, Phone, LogIn, LogOut, ShieldCheck } from '@lucide/vue'
import UiModal from '../components/UiModal.vue'
import { useAppStore } from '../stores/app'

const store = useAppStore()
const showInvite = ref(false)
const showQr = ref<string | null>(null)
const query = ref('')
const form = reactive({ name: '', company: '', phone: '', visitDate: new Date().toISOString().slice(0, 10), visitTime: '10:00', purpose: '', host: store.currentUser.name })
const filtered = computed(() => store.visitors.filter((item) => `${item.name}${item.company}${item.host}`.toLowerCase().includes(query.value.toLowerCase())))
const currentVisitor = computed(() => store.visitors.find((item) => item.id === showQr.value))
async function invite() { if (!form.name || !form.company || !form.phone) return; await store.createVisitor({ ...form }); showInvite.value = false; Object.assign(form, { name: '', company: '', phone: '', purpose: '' }) }
</script>

<template>
  <div class="space-y-6">
    <section class="relative overflow-hidden rounded-[1rem] bg-[#dfeae3] p-7 sm:p-9"><div class="absolute -right-12 -top-24 size-64 rounded-full border-[42px] border-white/30"></div><div class="relative flex flex-col justify-between gap-6 md:flex-row md:items-center"><div><p class="label text-forest/60">A WARM, SECURE WELCOME</p><h2 class="mt-3 text-3xl font-semibold tracking-[-.045em]">2.5층 라운지에서<br>매끄럽게 맞이하세요.</h2><p class="mt-3 text-sm text-black/45">사전 등록부터 QR 출입, 담당자 호출까지 하나로 연결됩니다.</p></div><button class="btn-primary shrink-0" @click="showInvite = true"><UserPlus :size="17" /> 방문객 초대</button></div></section>
    <section class="grid gap-4 sm:grid-cols-3"><article class="card flex items-center gap-4 p-5"><span class="grid size-11 place-items-center rounded-xl bg-blue-50 text-blue-600"><UserPlus :size="19" /></span><div><b class="text-2xl">{{ store.visitors.filter(v => v.visitDate === store.today).length }}</b><p class="text-[11px] text-black/40">오늘 예정</p></div></article><article class="card flex items-center gap-4 p-5"><span class="grid size-11 place-items-center rounded-xl bg-emerald-50 text-emerald-700"><LogIn :size="19" /></span><div><b class="text-2xl">{{ store.visitors.filter(v => v.status === 'arrived').length }}</b><p class="text-[11px] text-black/40">현재 방문 중</p></div></article><article class="card flex items-center gap-4 p-5"><span class="grid size-11 place-items-center rounded-xl bg-[#f1ede4] text-[#83693e]"><ShieldCheck :size="19" /></span><div><b class="text-2xl">100<small class="text-sm text-black/30">%</small></b><p class="text-[11px] text-black/40">출입 인증 완료율</p></div></article></section>
    <section class="card overflow-hidden"><header class="flex flex-col justify-between gap-4 border-b border-black/6 p-6 sm:flex-row sm:items-center"><div><p class="label">VISITOR LOG</p><h3 class="mt-2 text-lg font-semibold">방문 일정</h3></div><label class="flex items-center gap-2 rounded-xl bg-[#f3f4f1] px-3.5 py-2.5"><Search :size="15" class="text-black/35" /><input v-model="query" class="bg-transparent text-xs outline-none" placeholder="이름, 회사, 담당자 검색" /></label></header><div class="overflow-x-auto"><table class="w-full min-w-[800px] text-left"><thead><tr class="bg-[#f7f7f4] text-[10px] font-bold tracking-wider text-black/35"><th class="px-6 py-3.5">방문객</th><th class="px-4 py-3.5">방문 일시</th><th class="px-4 py-3.5">담당자 / 목적</th><th class="px-4 py-3.5">상태</th><th class="px-6 py-3.5 text-right">출입 관리</th></tr></thead><tbody class="divide-y divide-black/6"><tr v-for="visitor in filtered" :key="visitor.id" class="text-xs hover:bg-[#fafaf7]"><td class="px-6 py-4"><div class="flex items-center gap-3"><span class="grid size-9 place-items-center rounded-xl bg-mist font-bold text-forest">{{ visitor.name.slice(0, 1) }}</span><div><b>{{ visitor.name }}</b><p class="mt-1 flex items-center gap-1 text-[10px] text-black/40"><Building2 :size="11" />{{ visitor.company }}</p></div></div></td><td class="px-4 py-4"><b>{{ visitor.visitDate }}</b><p class="mt-1 flex items-center gap-1 text-[10px] text-black/40"><Clock3 :size="11" />{{ visitor.visitTime }}</p></td><td class="px-4 py-4"><b>{{ visitor.host }}</b><p class="mt-1 text-[10px] text-black/40">{{ visitor.purpose }}</p></td><td class="px-4 py-4"><span :class="['badge', visitor.status === 'arrived' ? 'bg-emerald-50 text-emerald-700' : visitor.status === 'departed' ? 'bg-black/5 text-black/45' : 'bg-blue-50 text-blue-700']">{{ visitor.status === 'arrived' ? '방문 중' : visitor.status === 'departed' ? '퇴실 완료' : '초대 완료' }}</span></td><td class="px-6 py-4"><div class="flex justify-end gap-2"><button class="btn-secondary !px-3 !py-2" @click="showQr = visitor.id"><QrCode :size="14" /> QR</button><button v-if="visitor.status === 'invited'" class="btn-primary !px-3 !py-2" @click="store.updateVisitorStatus(visitor.id, 'arrived')"><LogIn :size="14" /> 입실</button><button v-else-if="visitor.status === 'arrived'" class="btn-secondary !px-3 !py-2" @click="store.updateVisitorStatus(visitor.id, 'departed')"><LogOut :size="14" /> 퇴실</button></div></td></tr></tbody></table></div></section>

    <UiModal v-if="showInvite" title="방문객 초대" description="초대 즉시 방문용 QR 자격증명이 생성됩니다." @close="showInvite = false"><form class="space-y-4" @submit.prevent="invite"><div class="grid gap-4 sm:grid-cols-2"><label><span class="label mb-2 block">방문객 이름</span><input v-model="form.name" required class="field" placeholder="홍길동" /></label><label><span class="label mb-2 block">회사명</span><input v-model="form.company" required class="field" placeholder="회사명" /></label></div><label class="block"><span class="label mb-2 block">휴대전화</span><input v-model="form.phone" required class="field" placeholder="010-0000-0000" /></label><div class="grid grid-cols-2 gap-4"><label><span class="label mb-2 block">방문 날짜</span><input v-model="form.visitDate" type="date" class="field" /></label><label><span class="label mb-2 block">도착 시간</span><input v-model="form.visitTime" type="time" class="field" /></label></div><label class="block"><span class="label mb-2 block">방문 목적</span><input v-model="form.purpose" class="field" placeholder="프로젝트 미팅" /></label><label class="block"><span class="label mb-2 block">사내 담당자</span><input v-model="form.host" class="field" /></label><button class="btn-primary w-full"><UserPlus :size="16" /> 초대 및 QR 발급</button></form></UiModal>
    <UiModal v-if="showQr && currentVisitor" title="방문용 QR" :description="`${currentVisitor.name} · ${currentVisitor.visitDate} ${currentVisitor.visitTime}`" @close="showQr = null"><div class="text-center"><div class="mx-auto grid size-56 place-items-center rounded-3xl bg-white p-5 shadow-inner"><div class="grid size-full grid-cols-7 gap-1 bg-white p-1"><template v-for="i in 49" :key="i"><i :class="['rounded-[1px]', [1,2,3,4,5,6,7,8,12,14,15,17,19,21,22,23,24,25,26,27,29,31,33,35,36,38,40,42,43,44,45,46,47,48,49].includes(i) ? 'bg-[#10251d]' : 'bg-white']"></i></template></div></div><b class="mt-5 block tracking-[.18em]">{{ currentVisitor.qrCode }}</b><p class="mt-2 text-xs text-black/45">2.5F 라운지 게이트에서 스캔해 주세요.</p><div class="mt-5 flex items-center justify-center gap-2 text-[11px] text-black/40"><Phone :size="13" /> 담당자 {{ currentVisitor.host }} 자동 호출</div></div></UiModal>
  </div>
</template>
